def _word_hash(word):
    value = 0
    power = 1
    for char in word:
        value = (value + (CHAR_TO_ID.get(char, 1) + 17) * power) & ((1 << 64) - 1)
        power = (power * 131) & ((1 << 64) - 1)
    return value if value < (1 << 63) else value - (1 << 64)


