class Model:
    name = "local-exact-grammar-role-recurrence-event-cnn"
    idea = "reference subtypes recur across pronoun case forms"
    description = (
        "Trigram-heavy random filters and resolved subword bags represent local form, while semantic domains and "
        "closed-class channels cover eleven words. Eight broad roles encode change, transitions, and recurrence; "
        "exact grammar identity spans six words and personal pronouns span eleven. Category recurrence marks "
        "near, middle, far, or absent state. Seven reference subtypes pool pronoun case forms into speaker-singular, "
        "speaker-plural, listener, masculine, feminine, plural, and neutral recurrence traces."
    )
    insight = (
        "Shifted category timescales trailed the original split, restoring the champion recurrence bands. Long-range "
        "pronoun identity helped, but he/him/his are separate exact words; subtype recurrence tests coreference "
        "across grammatical case while preserving person, number, and gender distinctions."
    )
    n_params = (
        LEXICON_SIZE + len(GRAMMAR_WORD_HASHES)
        + sum(len(words) for words in BOUNDARY_WORD_HASHES)
        + len(MORPH_SUFFIXES) + CONV_PARAM_COUNT
    )

    def __init__(self):
        self._lexicon_tensors = {}
        self._grammar_hashes = torch.tensor(
            GRAMMAR_WORD_HASHES, dtype=torch.long
        ).view(1, -1)
        self._boundary_hashes = tuple(
            torch.tensor(values, dtype=torch.long).view(1, -1)
            for values in BOUNDARY_WORD_HASHES
        )
        generator = torch.Generator().manual_seed(404)
        self._char_embedding = torch.randn(
            N_CHAR_IDS, CHAR_EMBED_DIM, generator=generator
        ) / math.sqrt(CHAR_EMBED_DIM)
        self._conv_weights = [
            torch.randn(
                filters, CHAR_EMBED_DIM, kernel, generator=generator
            ) * math.sqrt(2.0 / (CHAR_EMBED_DIM * kernel))
            for filters, kernel in zip(CONV_FILTERS, CONV_KERNELS)
        ]
        self._conv_biases = [
            torch.randn(filters, generator=generator) * 0.03
            for filters in CONV_FILTERS
        ]

    def _semantic_features(self, word_hashes, device):
        key = str(device)
        lexicons = self._lexicon_tensors.get(key)
        if lexicons is None:
            lexicons = tuple(torch.tensor(values, device=device, dtype=torch.long).view(1, -1)
                             for values in LEXICON_HASHES)
            self._lexicon_tensors[key] = lexicons
        semantic = torch.zeros((word_hashes[0].shape[0], CATEGORY_OUT), device=device)
        current_categories, near_categories, middle_categories, far_categories = [], [], [], []
        category_histories = []
        for category, lexicon in enumerate(lexicons):
            memberships = [word_hash.eq(lexicon).any(dim=1).float() for word_hash in word_hashes]
            category_histories.append(torch.stack(memberships, dim=1))
            current_categories.append(memberships[0])
            near_categories.append(sum(memberships[age] for age in range(1, 4)))
            middle_categories.append(sum(memberships[age] for age in range(4, 8)))
            far_categories.append(
                sum(memberships[age] for age in range(8, len(memberships)))
            )
            semantic[:, category] = memberships[0]
            semantic[:, N_CATEGORIES + category] = sum(
                membership * (0.72 ** age) for age, membership in enumerate(memberships)
            )
            semantic[:, 2 * N_CATEGORIES + category] = sum(
                memberships[age] / age for age in range(1, min(6, len(memberships)))
            )
            semantic[:, 3 * N_CATEGORIES + category] = memberships[1]
            semantic[:, 4 * N_CATEGORIES + category] = sum(
                memberships[age] for age in range(1, 4)
            )
            semantic[:, 5 * N_CATEGORIES + category] = sum(
                memberships[age] for age in range(4, 8)
            )
            semantic[:, 6 * N_CATEGORIES + category] = sum(
                memberships[age] for age in range(8, len(memberships))
            )
            semantic[:, 7 * N_CATEGORIES + category] = memberships[2]
            semantic[:, 8 * N_CATEGORIES + category] = memberships[3]
            semantic[:, 9 * N_CATEGORIES + category] = memberships[4]
            semantic[:, 10 * N_CATEGORIES + category] = memberships[5]
            semantic[:, 11 * N_CATEGORIES + category] = memberships[6]
            semantic[:, 12 * N_CATEGORIES + category] = memberships[7]
            semantic[:, 13 * N_CATEGORIES + category] = memberships[8]
            semantic[:, 14 * N_CATEGORIES + category] = memberships[9]
            semantic[:, 15 * N_CATEGORIES + category] = memberships[10]

        current = torch.stack(current_categories, dim=1)
        context_bands = (
            torch.stack(near_categories, dim=1),
            torch.stack(middle_categories, dim=1),
            torch.stack(far_categories, dim=1),
        )
        categories = torch.arange(N_CATEGORIES, device=device)
        pair_hash = (
            categories.view(-1, 1) * 131 + categories.view(1, -1) * 17 + 19
        )
        interactions = torch.zeros(
            (current.shape[0], SEMANTIC_INTERACTION_OUT), device=device
        )
        signs = torch.where(
            torch.bitwise_and(
                categories.view(-1, 1) * 53 + categories.view(1, -1) * 97,
                1,
            ) == 0,
            1.0,
            -1.0,
        ).reshape(1, -1)
        offset = 0
        for width, context in zip(SEMANTIC_INTERACTION_WIDTHS, context_bands):
            products = (
                current.unsqueeze(2) * context.unsqueeze(1)
            ).reshape(current.shape[0], -1)
            bins = torch.remainder(pair_hash, width).reshape(1, -1)
            interactions.scatter_add_(
                1,
                bins.expand(current.shape[0], -1) + offset,
                products * signs,
            )
            offset += width
        category_history = torch.stack(category_histories, dim=2)
        return semantic, interactions, category_history

    def _wordslot_cnn(self, x, valid):
        n_batch, n_char = x.shape
        device = x.device
        pos = torch.arange(n_char, device=device).view(1, -1)
        lengths = valid.sum(dim=1, keepdim=True)
        source = pos - (n_char - lengths)
        right = x.gather(1, source.clamp(min=0, max=n_char - 1))
        right = torch.where(source.ge(0), right, torch.zeros_like(right))
        right_valid = right.ne(0)

        embedded = F.embedding(right, self._char_embedding.to(device))
        half = CHAR_EMBED_DIM // 2
        frequencies = torch.exp(
            -math.log(10000.0)
            * torch.arange(half, device=device, dtype=torch.float32)
            / max(1, half - 1)
        )
        angles = torch.arange(n_char, device=device, dtype=torch.float32).view(-1, 1)
        angles = angles * frequencies.view(1, -1)
        position = torch.cat((torch.sin(angles), torch.cos(angles)), dim=1)
        embedded = (embedded + 0.2 * position.view(1, n_char, -1))
        embedded = embedded * right_valid.unsqueeze(-1)

        spaces = right.eq(SPACE_ID)
        word_slot = torch.flip(
            torch.cumsum(torch.flip(spaces.long(), dims=(1,)), dim=1),
            dims=(1,),
        )
        content = right_valid & ~spaces
        outputs = []
        sequence = embedded.transpose(1, 2)
        for kernel, weight, bias in zip(
            CONV_KERNELS, self._conv_weights, self._conv_biases
        ):
            response = F.relu(F.conv1d(sequence, weight.to(device), bias.to(device)))
            width = response.shape[2]
            center = kernel // 2
            slot = word_slot[:, center:center + width]
            center_content = content[:, center:center + width]
            valid_window = right_valid.unfold(1, kernel, 1).all(dim=2)

            for age in range(WORD_SLOTS):
                mask = valid_window & center_content & slot.eq(age)
                count = mask.sum(dim=1, keepdim=True).clamp_min(1)
                pooled = (response * mask.unsqueeze(1)).sum(dim=2) / count
                outputs.append(pooled)
                peak = response.masked_fill(
                    ~mask.unsqueeze(1), float("-inf")
                ).amax(dim=2)
                peak = torch.where(torch.isfinite(peak), peak, torch.zeros_like(peak))
                outputs.append(peak)

            masked = response.masked_fill(~valid_window.unsqueeze(1), float("-inf"))
            global_max = masked.amax(dim=2)
            global_max = torch.where(torch.isfinite(global_max), global_max,
                                     torch.zeros_like(global_max))
            outputs.append(global_max)
        return torch.cat(outputs, dim=1)

    @staticmethod
    def _add(feat, offset, width, hashes, values):
        bins = torch.remainder(hashes, width).long() + offset
        signs = torch.where(torch.bitwise_and(hashes, 1) == 0, 1.0, -1.0)
        feat.scatter_add_(1, bins, values.float() * signs)

    @torch.no_grad()
    def __call__(self, X):
        x = torch.as_tensor(X).reshape(X.shape[0], -1).long()
        n_batch, n_char = x.shape
        device = x.device
        feat = torch.zeros((n_batch, D_OUT), device=device, dtype=torch.float32)

        pos = torch.arange(n_char, device=device).view(1, -1)
        valid = x.ne(0)
        spaces = x.eq(SPACE_ID)

        cumulative_spaces = spaces.long().cumsum(dim=1)
        recency = spaces.sum(dim=1, keepdim=True) - cumulative_spaces
        sep_pos = torch.cummax(torch.where(spaces, pos, -1), dim=1).values
        within_word = (pos - sep_pos - 1).clamp(min=0, max=31)
        powers = torch.pow(
            torch.full_like(within_word, 131, dtype=torch.long),
            within_word,
        )
        contribution = (x + 17) * powers
        word_hashes, boundary_word_hashes = [], []
        word_masks, word_exists, word_lengths = [], [], []
        for age in range(11):
            mask = valid & ~spaces & recency.eq(age)
            h = (contribution * mask.long()).sum(dim=1, keepdim=True)
            boundary_mask = mask.clone()
            for char_id in BOUNDARY_PUNCT_IDS:
                boundary_mask &= x.ne(char_id)
            boundary_h = (
                contribution * boundary_mask.long()
            ).sum(dim=1, keepdim=True)
            exists = mask.any(dim=1, keepdim=True).float()
            word_hashes.append(h)
            boundary_word_hashes.append(boundary_h)
            word_masks.append(mask)
            word_exists.append(exists)
            word_lengths.append(mask.sum(dim=1, keepdim=True))

        # Narrow, disjoint lexical banks for the current four words.
        for age in range(WORD_SLOTS):
            self._add(
                feat,
                age * WORD_SLOT_BINS,
                WORD_SLOT_BINS,
                word_hashes[age] + 32452843,
                word_exists[age],
            )

        # Older context shares one collision-heavy bank so identity remains reusable but regularized.
        context_offset = WORD_SLOT_OUT
        for age in range(1, len(word_hashes)):
            self._add(
                feat,
                context_offset,
                CONTEXT_BINS,
                word_hashes[age] + 49979687,
                word_exists[age] * (0.76 ** age),
            )

        # Slot-specific subword bags share morphology across distinct word identities.
        subword_offset = context_offset + CONTEXT_BINS
        for size, bins, offset in (
            (2, BIGRAM_BINS, subword_offset),
            (3, TRIGRAM_BINS, subword_offset + BIGRAM_OUT),
        ):
            width = n_char - size + 1
            hashes = torch.full(
                (n_batch, width), 2166136261 + 104729 * size,
                device=device, dtype=torch.long,
            )
            chars_by_shift = []
            for shift in range(size):
                chars = x[:, shift:shift + width]
                chars_by_shift.append(chars)
                hashes = hashes * 1000003 + chars + 37 * (shift + 1)
            for age in range(WORD_SLOTS):
                within_slot = torch.ones_like(hashes, dtype=torch.bool)
                for shift, chars in enumerate(chars_by_shift):
                    within_slot &= (
                        chars.ne(0)
                        & chars.ne(SPACE_ID)
                        & recency[:, shift:shift + width].eq(age)
                    )
                self._add(
                    feat,
                    offset + age * bins,
                    bins,
                    hashes,
                    within_slot.float() / math.sqrt(size),
                )

        # Exact suffix flags support a few grammatical forms without a wide affix identity bank.
        suffix_hashes = []
        for age in range(PHONO_SLOTS):
            mask = word_masks[age]
            word_end = torch.where(mask, pos, -1).amax(dim=1, keepdim=True)
            from_end = (word_end - pos).clamp(min=0, max=31)
            reverse_powers = torch.pow(torch.full_like(from_end, 131), from_end)
            reverse_contribution = (x + 17) * reverse_powers
            age_suffixes = {}
            for size in range(1, 6):
                suffix = (
                    reverse_contribution * (mask & from_end.lt(size)).long()
                ).sum(dim=1, keepdim=True)
                age_suffixes[size] = suffix
            suffix_hashes.append(age_suffixes)

        category_offset = subword_offset + BIGRAM_OUT + TRIGRAM_OUT
        semantic, semantic_interactions, category_history = (
            self._semantic_features(word_hashes, device)
        )
        feat[:, category_offset:category_offset + CATEGORY_OUT] = semantic

        grammar_offset = category_offset + CATEGORY_OUT
        grammar_hashes = self._grammar_hashes.to(device)
        grammar_memberships = [
            word_hashes[age].eq(grammar_hashes)
            for age in range(GRAMMAR_SLOTS)
        ]
        feat[:, grammar_offset:grammar_offset + GRAMMAR_OUT] = torch.cat(
            [
                membership.float()
                for membership in grammar_memberships[:GRAMMAR_IDENTITY_SLOTS]
            ],
            dim=1,
        )

        distant_grammar_offset = grammar_offset + GRAMMAR_OUT
        feat[
            :,
            distant_grammar_offset:
            distant_grammar_offset + DISTANT_GRAMMAR_OUT,
        ] = torch.cat(
            [
                grammar_memberships[age][
                    :, LONG_RANGE_GRAMMAR_INDICES
                ].float()
                for age in range(
                    GRAMMAR_IDENTITY_SLOTS, LONG_RANGE_IDENTITY_SLOTS
                )
            ],
            dim=1,
        )

        grammar_pair_offset = (
            distant_grammar_offset + DISTANT_GRAMMAR_OUT
        )
        for age in range(GRAMMAR_PAIR_GAPS):
            pair_exists = (
                grammar_memberships[age].any(dim=1, keepdim=True)
                & grammar_memberships[age + 1].any(dim=1, keepdim=True)
            )
            pair_hash = (
                word_hashes[age] * 1000003
                + word_hashes[age + 1] * 9176
                + 32452843
            )
            self._add(
                feat,
                grammar_pair_offset + age * GRAMMAR_PAIR_BINS,
                GRAMMAR_PAIR_BINS,
                pair_hash,
                pair_exists.float(),
            )

        event_offset = grammar_pair_offset + GRAMMAR_PAIR_OUT
        boundary_flags = torch.zeros(
            (n_batch, GRAMMAR_SLOTS, BOUNDARY_TYPE_OUT),
            device=device,
            dtype=torch.bool,
        )
        for age in range(GRAMMAR_SLOTS):
            punctuation = torch.zeros((n_batch, 1), device=device, dtype=torch.bool)
            for char_id in BOUNDARY_PUNCT_IDS:
                punctuation |= (x.eq(char_id) & word_masks[age]).any(
                    dim=1, keepdim=True
                )
            boundary_flags[:, age, 0:1] = punctuation
            for boundary_type, hashes in enumerate(self._boundary_hashes, start=1):
                boundary_flags[:, age, boundary_type:boundary_type + 1] = (
                    boundary_word_hashes[age]
                    .eq(hashes.to(device))
                    .any(dim=1, keepdim=True)
                )

        ages = torch.arange(GRAMMAR_SLOTS, device=device).view(1, -1)
        boundary_candidates = torch.where(
            boundary_flags.any(dim=2),
            ages,
            torch.full_like(ages, GRAMMAR_SLOTS),
        )
        boundary_age = boundary_candidates.amin(dim=1)
        boundary_recency = F.one_hot(
            boundary_age, num_classes=BOUNDARY_RECENCY_OUT
        ).float()
        nearest_age = boundary_age.clamp_max(GRAMMAR_SLOTS - 1)
        nearest_types = boundary_flags.gather(
            1,
            nearest_age.view(-1, 1, 1).expand(-1, 1, BOUNDARY_TYPE_OUT),
        ).squeeze(1).float()
        nearest_types = nearest_types * boundary_age.lt(
            GRAMMAR_SLOTS
        ).view(-1, 1)

        decay = torch.pow(
            torch.tensor(0.82, device=device),
            ages.float(),
        )
        current_mask = ages.lt(boundary_age.view(-1, 1)).float() * decay
        prior_mask = ages.gt(boundary_age.view(-1, 1)).float() * decay
        current_event = (
            category_history * current_mask.unsqueeze(2)
        ).sum(dim=1)
        prior_event = (
            category_history * prior_mask.unsqueeze(2)
        ).sum(dim=1)
        boundary_exists = boundary_age.lt(GRAMMAR_SLOTS).float().view(-1, 1)
        boundary_timescales = torch.cat(
            [
                torch.exp(-boundary_age.float().view(-1, 1) / scale)
                * boundary_exists
                for scale in BOUNDARY_TIMESCALES
            ],
            dim=1,
        )
        typed_triggers = category_history[
            :, 0, TYPED_TRIGGER_CATEGORY_INDICES
        ]
        trigger_boundary = (
            typed_triggers.unsqueeze(2)
            * boundary_timescales.unsqueeze(1)
        ).reshape(n_batch, -1)
        semantic_bands = (
            category_history[:, 0],
            category_history[:, 1:4].mean(dim=1),
            category_history[:, 4:8].mean(dim=1),
            category_history[:, 8:].mean(dim=1),
        )
        topic_drift = torch.stack(
            [
                (left - right).abs().mean(dim=1)
                for left, right in zip(
                    semantic_bands[:-1], semantic_bands[1:]
                )
            ],
            dim=1,
        )
        trigger_topic_drift = (
            category_history[:, 0].unsqueeze(2)
            * topic_drift.unsqueeze(1)
        ).reshape(n_batch, -1)
        role_history = torch.stack(
            [
                category_history[:, :, indices].amax(dim=2)
                for indices in DISCOURSE_ROLE_CATEGORY_INDICES
            ],
            dim=2,
        )
        prior_role_ages = torch.arange(
            1, GRAMMAR_SLOTS, device=device
        ).view(1, -1, 1)
        prior_role_age_values = torch.where(
            role_history[:, 1:].gt(0),
            prior_role_ages,
            torch.full_like(prior_role_ages, GRAMMAR_SLOTS),
        )
        nearest_role_age = prior_role_age_values.amin(dim=1)
        role_recency_codes = F.one_hot(
            nearest_role_age - 1,
            num_classes=ROLE_RECENCY_CLASSES,
        ).float()
        role_recency = role_recency_codes.reshape(n_batch, -1)
        current_role_recurrence = (
            role_history[:, 0].unsqueeze(2) * role_recency_codes
        ).reshape(n_batch, -1)
        reference_subtype_history = torch.stack(
            [
                torch.stack(
                    [
                        grammar_memberships[age][
                            :, indices
                        ].any(dim=1).float()
                        for indices in REFERENCE_SUBTYPE_INDICES
                    ],
                    dim=1,
                )
                for age in range(GRAMMAR_SLOTS)
            ],
            dim=1,
        )
        nearest_reference_subtype_age = torch.where(
            reference_subtype_history[:, 1:].gt(0),
            prior_role_ages,
            torch.full_like(prior_role_ages, GRAMMAR_SLOTS),
        ).amin(dim=1)
        reference_subtype_recency_codes = F.one_hot(
            nearest_reference_subtype_age - 1,
            num_classes=ROLE_RECENCY_CLASSES,
        ).float()
        reference_subtype_recency = (
            reference_subtype_recency_codes.reshape(n_batch, -1)
        )
        current_reference_subtype_recurrence = (
            reference_subtype_history[:, 0].unsqueeze(2)
            * reference_subtype_recency_codes
        ).reshape(n_batch, -1)
        prior_category_ages = torch.arange(
            1, GRAMMAR_SLOTS, device=device
        ).view(1, -1, 1)
        nearest_category_age = torch.where(
            category_history[
                :, 1:, RECURRENT_CATEGORY_INDICES
            ].gt(0),
            prior_category_ages,
            torch.full_like(prior_category_ages, GRAMMAR_SLOTS),
        ).amin(dim=1)
        category_recency_band = torch.where(
            nearest_category_age.le(3),
            torch.zeros_like(nearest_category_age),
            torch.where(
                nearest_category_age.le(7),
                torch.ones_like(nearest_category_age),
                torch.where(
                    nearest_category_age.le(10),
                    torch.full_like(nearest_category_age, 2),
                    torch.full_like(nearest_category_age, 3),
                ),
            ),
        )
        category_recency = F.one_hot(
            category_recency_band,
            num_classes=CATEGORY_RECENCY_BANDS,
        ).float().reshape(n_batch, -1)
        role_bands = (
            role_history[:, 0],
            role_history[:, 1:4].mean(dim=1),
            role_history[:, 4:8].mean(dim=1),
            role_history[:, 8:].mean(dim=1),
        )
        role_topic_drift = torch.stack(
            [
                (left - right).abs()
                for left, right in zip(role_bands[:-1], role_bands[1:])
            ],
            dim=1,
        )
        role_topic_interactions = (
            role_history[:, 0].view(n_batch, 1, DISCOURSE_ROLE_COUNT, 1)
            * role_topic_drift.unsqueeze(2)
        ).reshape(n_batch, -1)
        role_context = torch.stack(role_bands[1:], dim=1)
        role_context_interactions = (
            role_history[:, 0].view(n_batch, 1, DISCOURSE_ROLE_COUNT, 1)
            * role_context.unsqueeze(2)
        ).reshape(n_batch, -1)
        role_band_transitions = torch.cat(
            [
                (
                    role_bands[left].unsqueeze(2)
                    * role_bands[right].unsqueeze(1)
                ).reshape(n_batch, -1)
                for left, right in ((1, 2), (2, 3))
            ],
            dim=1,
        )
        current_grammar = category_history[:, 0, GRAMMAR_CATEGORY_INDICES]
        grammar_role_context = (
            current_grammar.view(
                n_batch, 1, len(GRAMMAR_CATEGORIES), 1
            )
            * role_context[:, :GRAMMAR_ROLE_CONTEXT_BANDS].unsqueeze(2)
        ).reshape(n_batch, -1)

        categories = torch.arange(N_CATEGORIES, device=device)
        event_pair_hash = (
            categories.view(-1, 1) * 131
            + categories.view(1, -1) * 17
            + 104729
        )
        event_bins = torch.remainder(
            event_pair_hash, EVENT_INTERACTION_BINS
        ).reshape(1, -1)
        event_signs = torch.where(
            torch.bitwise_and(
                categories.view(-1, 1) * 97
                + categories.view(1, -1) * 53,
                1,
            ) == 0,
            1.0,
            -1.0,
        ).reshape(1, -1)
        event_interactions = torch.zeros(
            (n_batch, EVENT_INTERACTION_BINS), device=device
        )
        event_interactions.scatter_add_(
            1,
            event_bins.expand(n_batch, -1),
            (
                category_history[:, 0].unsqueeze(2)
                * prior_event.unsqueeze(1)
            ).reshape(n_batch, -1) * event_signs,
        )
        boundary_condition = (
            nearest_types.unsqueeze(2)
            * category_history[:, 0].unsqueeze(1)
        ).reshape(n_batch, -1)
        feat[:, event_offset:event_offset + EVENT_OUT] = torch.cat(
            (
                boundary_recency,
                nearest_types,
                current_event,
                prior_event,
                event_interactions,
                boundary_condition,
                trigger_boundary,
                topic_drift,
                trigger_topic_drift,
                role_topic_drift.reshape(n_batch, -1),
                role_topic_interactions,
                role_context_interactions,
                role_band_transitions,
                grammar_role_context,
                role_recency,
                current_role_recurrence,
                category_recency,
                reference_subtype_recency,
                current_reference_subtype_recurrence,
            ),
            dim=1,
        )

        # Low-dimensional spelling and phonological proxies for the four most recent words.
        shape_offset = event_offset + EVENT_OUT
        is_letter = x.ge(LETTER_MIN) & x.le(LETTER_MAX)
        is_digit = x.ge(DIGIT_MIN) & x.le(DIGIT_MAX)
        is_vowel = torch.zeros_like(valid)
        for char_id in VOWEL_IDS:
            is_vowel |= x.eq(char_id)
        is_labial = torch.zeros_like(valid)
        for char_id in LABIAL_IDS:
            is_labial |= x.eq(char_id)
        is_coronal = torch.zeros_like(valid)
        for char_id in CORONAL_IDS:
            is_coronal |= x.eq(char_id)
        is_dorsal = torch.zeros_like(valid)
        for char_id in DORSAL_IDS:
            is_dorsal |= x.eq(char_id)
        is_sibilant = torch.zeros_like(valid)
        for char_id in SIBILANT_IDS:
            is_sibilant |= x.eq(char_id)
        prev_vowel = F.pad(is_vowel[:, :-1], (1, 0))
        vowel_onset = is_vowel & ~prev_vowel
        repeated = F.pad(x[:, 1:].eq(x[:, :-1]), (1, 0))
        for age in range(FORM_SLOTS):
            mask = word_masks[age]
            length = word_lengths[age].float()
            denominator = length.clamp_min(1)
            end = torch.where(mask, pos, -1).amax(dim=1, keepdim=True)
            start = torch.where(mask, pos, n_char).amin(dim=1, keepdim=True)
            first_vowel = (is_vowel & pos.eq(start)).any(dim=1, keepdim=True).float()
            last_vowel = (is_vowel & pos.eq(end)).any(dim=1, keepdim=True).float()
            stats = (
                torch.log1p(length),
                (is_vowel & mask).sum(dim=1, keepdim=True) / denominator,
                (is_letter & ~is_vowel & mask).sum(dim=1, keepdim=True) / denominator,
                (is_digit & mask).sum(dim=1, keepdim=True),
                (vowel_onset & mask).sum(dim=1, keepdim=True),
                (repeated & mask).sum(dim=1, keepdim=True),
                (x.eq(CHAR_TO_ID["'"]) & mask).any(dim=1, keepdim=True).float(),
                (x.eq(CHAR_TO_ID["-"]) & mask).any(dim=1, keepdim=True).float(),
                first_vowel,
                last_vowel,
                word_lengths[age].ge(8).float(),
                word_lengths[age].ge(3).float(),
            )
            feat[:, shape_offset + 12 * age:shape_offset + 12 * (age + 1)] = (
                torch.cat(stats, dim=1)
            )

        for suffix_index, (size, suffix_hash) in enumerate(MORPH_SUFFIX_HASHES):
            current_match = (
                suffix_hashes[0][size].eq(suffix_hash)
                & word_lengths[0].ge(size)
            ).float()
            context_match = sum(
                (
                    suffix_hashes[age][size].eq(suffix_hash)
                    & word_lengths[age].ge(size)
                ).float() * (0.72 ** age)
                for age in range(1, 6)
            )
            feat[:, shape_offset + 48 + suffix_index:shape_offset + 49 + suffix_index] = (
                current_match
            )
            feat[:, shape_offset + 64 + suffix_index:shape_offset + 65 + suffix_index] = (
                context_match
            )

        discourse_offset = shape_offset + SHAPE_OUT
        feat[
            :, discourse_offset:discourse_offset + SEMANTIC_INTERACTION_OUT
        ] = semantic_interactions

        band_offset = discourse_offset + SEMANTIC_INTERACTION_OUT
        for band, (start_age, stop_age) in enumerate(((1, 4), (4, 8), (8, 11))):
            for age in range(start_age, stop_age):
                self._add(
                    feat,
                    band_offset + band * CONTEXT_BAND_BINS,
                    CONTEXT_BAND_BINS,
                    word_hashes[age] + 104395301,
                    word_exists[age] / math.sqrt(stop_age - start_age),
                )

        older_offset = band_offset + CONTEXT_BAND_OUT
        for age in range(4, len(word_hashes)):
            self._add(
                feat,
                older_offset + (age - 4) * OLDER_SLOT_BINS,
                OLDER_SLOT_BINS,
                word_hashes[age] + 86028121,
                word_exists[age],
            )

        phono_offset = discourse_offset + DISCOURSE_OUT
        for age in range(PHONO_SLOTS):
            mask = word_masks[age]
            length = word_lengths[age].float()
            denominator = length.clamp_min(1)
            start = torch.where(mask, pos, n_char).amin(dim=1, keepdim=True)
            end = torch.where(mask, pos, -1).amax(dim=1, keepdim=True)
            at_start = pos.eq(start)
            at_end = pos.eq(end)
            phonology = (
                torch.log1p(length),
                (is_vowel & mask).sum(dim=1, keepdim=True) / denominator,
                (is_letter & ~is_vowel & mask).sum(dim=1, keepdim=True) / denominator,
                (vowel_onset & mask).sum(dim=1, keepdim=True),
                (repeated & mask).sum(dim=1, keepdim=True),
                (is_digit & mask).sum(dim=1, keepdim=True),
                (is_vowel & at_start).any(dim=1, keepdim=True).float(),
                (is_vowel & at_end).any(dim=1, keepdim=True).float(),
                (is_labial & at_start).any(dim=1, keepdim=True).float(),
                (is_coronal & at_start).any(dim=1, keepdim=True).float(),
                (is_dorsal & at_start).any(dim=1, keepdim=True).float(),
                (is_sibilant & at_start).any(dim=1, keepdim=True).float(),
                (is_labial & at_end).any(dim=1, keepdim=True).float(),
                (is_coronal & at_end).any(dim=1, keepdim=True).float(),
                (is_dorsal & at_end).any(dim=1, keepdim=True).float(),
                (is_sibilant & at_end).any(dim=1, keepdim=True).float(),
            )
            feat[
                :, phono_offset + age * PHONO_PER_SLOT:
                phono_offset + (age + 1) * PHONO_PER_SLOT
            ] = torch.cat(phonology, dim=1)

        feat[:, BASE_OUT:] = self._wordslot_cnn(x, valid)
        return feat


MODEL = Model()
